local function C_d()
local script = G2L["d"];
	local button = script.Parent

	local function switchToPoopyPants()
		local screenGui = button:FindFirstAncestorWhichIsA("ScreenGui")
		if not screenGui then return end

		for _, frame in ipairs(screenGui:GetDescendants()) do
			if frame:IsA("Frame") and frame.Name ~= "poopy pants?" then
				if not frame:IsAncestorOf(button) then
					frame.Visible = false
				end
			end
		end

		local poopyFrame = screenGui:FindFirstChild("poopy pants?", true)
		if poopyFrame then
			poopyFrame.Visible = true
		end

		local innerFrame = button:FindFirstChildWhichIsA("Frame")
		if innerFrame then
			innerFrame.Visible = true
		end
	end

	button.MouseButton1Click:Connect(switchToPoopyPants)
end;
task.spawn(C_d);
