		for _, obj in ipairs(player:GetDescendants()) do
			if obj.Name == "SyncAPI" then
				tool = obj.Parent
				break
			end
		end

		if not tool then
			for _, folder in ipairs({player.PlayerGui, player.Backpack, player.Character}) do
				if folder then
					for _, obj in ipairs(folder:GetDescendants()) do
						if obj.Name == "SyncAPI" then
							tool = obj.Parent
							break
						end
					end
					if tool then break end
				end
			end
		end

		if not tool then return end
		local remote = tool:FindFirstChild("SyncAPI") and tool.SyncAPI:FindFirstChild("ServerEndpoint")
		if not remote then return end

		local function GetPartsFromSelection(Selection)
			local Parts = {}
			for _, Descendant in pairs(Selection:GetDescendants()) do
				if Descendant:IsA('BasePart') 
					and Descendant.Name ~= "Terrain" 
					and not tostring(Descendant.Name):find("youridentifierpleasemakethisunique") 
					and not tostring(Descendant.Name):find("Sky") then
					Parts[#Parts + 1] = Descendant
				end
			end
			return Parts
		end

