			local char, hrp = getChar()

			local radius = 5
			local verticalAmplitude = 3
			local speed = math.rad(100)
			local angle = 0

			local initialCF = hrp.CFrame * CFrame.new(radius, -0.1, 0)

			CreatePart(initialCF, workspace)

			local ball

			repeat task.wait()
				for _,v in ipairs(workspace:GetDescendants()) do
